// Raisonnement logique (banque complémentaire lo2) : suites numériques, suites de lettres et de mots,
// codages, calendriers, horloges, probabilités, dénombrement, parenté, syllogismes, menteurs,
// classements, problèmes arithmétiques, intrus, analogies, tableaux décrits en texte, conversions.
// Chaque réponse a été vérifiée par un script node (calcul ou recherche exhaustive).
BANK.push(
// --- Suites numériques ---
{id:"lo2-001",t:"log",q:"Quel nombre suit : 7 – 11 – 15 – 19 – ?",o:["21","23","25","27"],a:1,e:"Suite arithmétique : on ajoute 4 à chaque terme (19 + 4 = 23).",s:"Banque logique"},
{id:"lo2-002",t:"log",q:"Quel nombre suit : 96 – 48 – 24 – 12 – ?",o:["6","4","8","10"],a:0,e:"Chaque terme est la moitié du précédent : 12 / 2 = 6.",s:"Banque logique"},
{id:"lo2-003",t:"log",q:"Quel nombre suit : 5 – 15 – 45 – 135 – ?",o:["270","375","540","405"],a:3,e:"Suite géométrique de raison 3 : 135 × 3 = 405.",s:"Banque logique"},
{id:"lo2-004",t:"log",q:"Quel nombre suit : 2 – 5 – 10 – 17 – 26 – ?",o:["35","36","37","39"],a:2,e:"Écarts 3, 5, 7, 9, puis 11 : 26 + 11 = 37 (ce sont les carrés augmentés de 1).",s:"Banque logique"},
{id:"lo2-005",t:"log",q:"Quel nombre suit : 3 – 12 – 27 – 48 – ?",o:["69","72","81","75"],a:3,e:"Triple des carrés : 3 × 1², 3 × 2², 3 × 3², 3 × 4², puis 3 × 5² = 75 (écarts 9, 15, 21, 27).",s:"Banque logique"},
{id:"lo2-006",t:"log",q:"Quel nombre complète cette suite de nombres premiers : 47 – 53 – 59 – 61 – ?",o:["67","63","65","69"],a:0,e:"Le nombre premier qui suit 61 est 67 ; 63 = 7 × 9, 65 = 5 × 13 et 69 = 3 × 23.",s:"Banque logique"},
{id:"lo2-007",t:"log",q:"Quel nombre suit : 1 – 3 – 6 – 10 – 15 – ?",o:["20","21","22","25"],a:1,e:"Nombres triangulaires : on ajoute 2, 3, 4, 5, puis 6 : 15 + 6 = 21.",s:"Banque logique"},
{id:"lo2-008",t:"log",q:"Quel nombre suit : 1 – 2 – 6 – 24 – 120 – ?",o:["240","600","720","840"],a:2,e:"On multiplie successivement par 2, 3, 4, 5, puis 6 : 120 × 6 = 720.",s:"Banque logique"},
{id:"lo2-009",t:"log",q:"Quel nombre suit : 3 – 4 – 7 – 11 – 18 – 29 – ?",o:["40","43","58","47"],a:3,e:"Chaque terme est la somme des deux précédents : 18 + 29 = 47.",s:"Banque logique"},
{id:"lo2-010",t:"log",q:"Quel nombre vient ensuite : 2 – 9 – 4 – 8 – 6 – 7 – ?",o:["8","5","6","10"],a:0,e:"Deux suites alternées : rangs impairs 2, 4, 6, 8 (+ 2) et rangs pairs 9, 8, 7 (− 1). Le 7e terme est 8.",s:"Banque logique"},
{id:"lo2-011",t:"log",q:"Quel nombre suit : 0 – 7 – 26 – 63 – ?",o:["99","124","125","127"],a:1,e:"Cubes moins 1 : 1³ − 1, 2³ − 1, 3³ − 1, 4³ − 1, puis 5³ − 1 = 124.",s:"Banque logique"},
{id:"lo2-012",t:"log",q:"Quel nombre suit : 1 – 4 – 27 – 256 – ?",o:["625","1 024","3 125","4 096"],a:2,e:"Chaque entier est élevé à sa propre puissance : 1¹, 2², 3³, 4⁴, puis 5⁵ = 3 125.",s:"Banque logique"},
{id:"lo2-013",t:"log",q:"Quel nombre suit : 4 – 9 – 19 – 39 – 79 – ?",o:["118","158","160","159"],a:3,e:"Chaque terme est le double du précédent plus 1 : 79 × 2 + 1 = 159.",s:"Banque logique"},
{id:"lo2-014",t:"log",q:"Quel nombre vient ensuite : 2 – 5 – 4 – 7 – 6 – 9 – ?",o:["8","7","10","12"],a:0,e:"On alterne + 3 et − 1 : 9 − 1 = 8.",s:"Banque logique"},
{id:"lo2-015",t:"log",q:"Quel nombre manque : 29 – 31 – ? – 41 – 43",o:["33","37","35","39"],a:1,e:"Ce sont des nombres premiers consécutifs : 29, 31, 37, 41, 43 (33, 35 et 39 ne sont pas premiers).",s:"Banque logique"},
{id:"lo2-016",t:"log",q:"Quel nombre suit : 2 – 12 – 36 – 80 – 150 – ?",o:["216","240","252","294"],a:2,e:"Terme = n² × (n + 1) : 1 × 2, 4 × 3, 9 × 4, 16 × 5, 25 × 6, puis 36 × 7 = 252.",s:"Banque logique"},
{id:"lo2-017",t:"log",q:"Quel nombre suit : 1 – 2 – 5 – 14 – 41 – ?",o:["82","121","123","122"],a:3,e:"Chaque terme est le triple du précédent moins 1 : 41 × 3 − 1 = 122 (les écarts 1, 3, 9, 27, 81 triplent).",s:"Banque logique"},
{id:"lo2-018",t:"log",q:"Quel nombre suit : 1 – 4 – 10 – 22 – 46 – ?",o:["94","70","92","96"],a:0,e:"Chaque terme vaut le double du précédent plus 2 : 46 × 2 + 2 = 94 (écarts 3, 6, 12, 24, 48).",s:"Banque logique"},
{id:"lo2-019",t:"log",q:"Quel nombre suit : 6 – 11 – 21 – 36 – 56 – ?",o:["76","81","80","86"],a:1,e:"Les écarts augmentent de 5 : 5, 10, 15, 20, puis 25 : 56 + 25 = 81.",s:"Banque logique"},
{id:"lo2-020",t:"log",q:"Quel nombre vient ensuite : 1 – 4 – 2 – 8 – 3 – 16 – 4 – ?",o:["5","20","32","24"],a:2,e:"Rangs impairs : 1, 2, 3, 4 ; rangs pairs : 4, 8, 16, puis 32 (× 2). Le 8e terme est 32.",s:"Banque logique"},
{id:"lo2-021",t:"log",q:"Quel nombre suit : 0 – 1 – 1 – 2 – 4 – 7 – 13 – ?",o:["20","21","26","24"],a:3,e:"Chaque terme est la somme des trois précédents : 4 + 7 + 13 = 24.",s:"Banque logique"},
{id:"lo2-022",t:"log",q:"Quel nombre suit : 5 – 6 – 8 – 12 – 20 – ?",o:["36","28","32","40"],a:0,e:"Les écarts doublent : 1, 2, 4, 8, puis 16 : 20 + 16 = 36.",s:"Banque logique"},
{id:"lo2-023",t:"log",q:"Quel nombre vient ensuite : 1 – 3 – 2 – 6 – 5 – 15 – 14 – ?",o:["13","42","28","45"],a:1,e:"On alterne × 3 et − 1 : 14 × 3 = 42.",s:"Banque logique"},
{id:"lo2-024",t:"log",q:"Quel nombre suit : 81 – 64 – 49 – 36 – ?",o:["16","27","25","30"],a:2,e:"Carrés décroissants : 9², 8², 7², 6², puis 5² = 25.",s:"Banque logique"},
{id:"lo2-025",t:"log",q:"Quel nombre suit : 2 – 6 – 30 – 210 – 2 310 – ?",o:["25 410","27 720","34 650","30 030"],a:3,e:"On multiplie par les nombres premiers successifs 3, 5, 7, 11, puis 13 : 2 310 × 13 = 30 030.",s:"Banque logique"},
{id:"lo2-026",t:"log",q:"Quel nombre suit : 1 – 9 – 25 – 49 – 81 – ?",o:["121","100","144","169"],a:0,e:"Carrés des nombres impairs : 1², 3², 5², 7², 9², puis 11² = 121 (écarts 8, 16, 24, 32, 40).",s:"Banque logique"},
{id:"lo2-027",t:"log",q:"Quel nombre suit : 1 – 2 – 4 – 8 – 15 – 26 – ?",o:["37","42","40","52"],a:1,e:"Écarts 1, 2, 4, 7, 11 : ils augmentent de 1, 2, 3, 4, puis 5. Écart suivant 16 : 26 + 16 = 42.",s:"Banque logique"},
// --- Suites de lettres et alphanumériques ---
{id:"lo2-028",t:"log",q:"Quelle lettre suit : Y – V – S – P – ?",o:["N","L","M","O"],a:2,e:"On recule de trois lettres : P (16) − 3 = M (13).",s:"Banque logique"},
{id:"lo2-029",t:"log",q:"Complétez : AB – DE – GH – JK – ?",o:["LM","NO","MO","MN"],a:3,e:"Deux lettres consécutives, puis on en saute une : AB (C) DE (F) GH (I) JK (L) MN.",s:"Banque logique"},
{id:"lo2-030",t:"log",q:"Complétez : A1 – B2 – D4 – H8 – ?",o:["P16","I9","O15","Q17"],a:0,e:"Le nombre double à chaque fois et la lettre est celle de ce rang dans l'alphabet : 16 = P.",s:"Banque logique"},
{id:"lo2-031",t:"log",q:"Complétez : A2 – C6 – E10 – G14 – ?",o:["H16","I18","I16","J18"],a:1,e:"Une lettre sur deux ; le nombre est le double du rang de la lettre : I = 9, donc 18.",s:"Banque logique"},
{id:"lo2-032",t:"log",q:"Complétez : B1 – D8 – F27 – H64 – ?",o:["I81","J100","J125","K125"],a:2,e:"Une lettre sur deux (B, D, F, H, J) et les cubes 1, 8, 27, 64, 125.",s:"Banque logique"},
{id:"lo2-033",t:"log",q:"Complétez : AZ – CX – EV – GT – ?",o:["HS","IS","JR","IR"],a:3,e:"La première lettre avance de deux rangs, la seconde recule de deux : I et R.",s:"Banque logique"},
{id:"lo2-034",t:"log",q:"Quelle lettre suit : J – F – M – A – M – J – J – ?",o:["A","S","O","J"],a:0,e:"Initiales des mois : janvier, février, mars, avril, mai, juin, juillet, puis août.",s:"Banque logique"},
{id:"lo2-035",t:"log",q:"Quelle lettre suit : U – D – T – Q – C – S – S – ?",o:["N","H","D","O"],a:1,e:"Initiales des nombres : un, deux, trois, quatre, cinq, six, sept, puis huit.",s:"Banque logique"},
{id:"lo2-036",t:"log",q:"Complétez : ACE – BDF – CEG – ?",o:["DEF","EGI","DFH","CFH"],a:2,e:"Chaque bloc prend une lettre sur deux, et chaque bloc commence une lettre plus loin que le précédent : DFH.",s:"Banque logique"},
{id:"lo2-037",t:"log",q:"Quelle lettre suit : A – C – G – M – ?",o:["S","T","W","U"],a:3,e:"Rangs 1, 3, 7, 13 : écarts 2, 4, 6, puis 8 : 13 + 8 = 21, soit U.",s:"Banque logique"},
{id:"lo2-038",t:"log",q:"Quelle lettre suit : B – C – D – F – G – H – J – ?",o:["K","I","L","M"],a:0,e:"Ce sont les consonnes dans l'ordre alphabétique : après J vient K.",s:"Banque logique"},
{id:"lo2-039",t:"log",q:"Complétez : 1A – 3C – 6F – 10J – ?",o:["14N","15O","15N","16P"],a:1,e:"Nombres triangulaires (écarts 2, 3, 4, puis 5) et lettre du même rang : 15 = O.",s:"Banque logique"},
{id:"lo2-040",t:"log",q:"Complétez : 2B – 3C – 5E – 7G – 11K – ?",o:["12L","13L","13M","15O"],a:2,e:"Nombres premiers successifs, avec la lettre de même rang : 13 = M.",s:"Banque logique"},
{id:"lo2-041",t:"log",q:"Quelle lettre suit : Z – W – S – N – ?",o:["G","I","J","H"],a:3,e:"Rangs 26, 23, 19, 14 : on recule de 3, 4, 5, puis 6 : 14 − 6 = 8, soit H.",s:"Banque logique"},
// --- Suites de mots à règle cachée ---
{id:"lo2-042",t:"log",q:"Quel mot complète la série : OR – AIR – CIEL – TERRE – ?",o:["SOLEIL","LUNE","NUAGE","PLANÈTE"],a:0,e:"Le nombre de lettres augmente de 1 : 2, 3, 4, 5, puis 6 (SOLEIL).",s:"Banque logique"},
{id:"lo2-043",t:"log",q:"Quel mot complète la série : BALLE – CARTE – DOUCHE – ESCALIER – ?",o:["ARMOIRE","FENÊTRE","GARAGE","DOMINO"],a:1,e:"Les initiales suivent l'alphabet : B, C, D, E, puis F.",s:"Banque logique"},
{id:"lo2-044",t:"log",q:"Quel mot complète la série : PARIS – SOLEIL – LAPIN – NAVIRE – ?",o:["ARBRE","ORANGE","ENCRE","TIGRE"],a:2,e:"Chaque mot commence par la dernière lettre du précédent : NAVIRE finit par E, d'où ENCRE.",s:"Banque logique"},
{id:"lo2-045",t:"log",q:"Quel mot complète la série : AMI – CHAT – ENFANT – GARE – ?",o:["HIBOU","JARDIN","KIWI","IGLOO"],a:3,e:"Les initiales avancent de deux lettres : A, C, E, G, puis I.",s:"Banque logique"},
{id:"lo2-046",t:"log",q:"Rangés dans l'ordre alphabétique, quel mot arrive en troisième position : FACTURE, FACTEUR, FACTION, FACILE ?",o:["FACTION","FACILE","FACTEUR","FACTURE"],a:0,e:"FACI précède FACT ; puis FACTE, FACTI, FACTU : FACILE, FACTEUR, FACTION, FACTURE.",s:"Banque logique"},
{id:"lo2-047",t:"log",q:"Quel mot complète la série : CODA – CLUB – ARC – BLED – ?",o:["LOUP","TIGRE","OURS","LYNX"],a:1,e:"Les dernières lettres suivent l'alphabet : A, B, C, D, puis E (TIGRE).",s:"Banque logique"},
{id:"lo2-048",t:"log",q:"Quel mot complète la série : CHOCOLAT – BISCUIT – GÂTEAU – TARTE – ?",o:["CRÊPE","BEIGNET","PAIN","BRIOCHE"],a:2,e:"Le nombre de lettres diminue de 1 : 8, 7, 6, 5, puis 4 (PAIN).",s:"Banque logique"},
{id:"lo2-049",t:"log",q:"Quel mot complète la série : MER – AMER – RAMER – ?",o:["RAMES","MARRE","AMERS","TRAMER"],a:3,e:"On ajoute à chaque fois une lettre devant le mot précédent : MER, A-MER, R-AMER, T-RAMER.",s:"Banque logique"},
// --- Codages ---
{id:"lo2-050",t:"log",q:"Si PAIN s'écrit RCKP, comment s'écrit LAIT ?",o:["NCKV","MBJU","NCJV","OCKV"],a:0,e:"Chaque lettre avance de deux rangs : L → N, A → C, I → K, T → V.",s:"Banque logique"},
{id:"lo2-051",t:"log",q:"Si CODE s'écrit BNCD, comment s'écrit IMPOT ?",o:["JNQPU","HLONS","HLNOS","HKONS"],a:1,e:"Chaque lettre recule d'un rang : I → H, M → L, P → O, O → N, T → S.",s:"Banque logique"},
{id:"lo2-052",t:"log",q:"Si SEL s'écrit MFT et VIN s'écrit OJW, comment s'écrit TAXE ?",o:["UBYF","FXAT","FYBU","EYBU"],a:2,e:"On écrit le mot à l'envers, puis chaque lettre avance d'un rang : TAXE → EXAT → FYBU.",s:"Banque logique"},
{id:"lo2-053",t:"log",q:"Le mot LAIT vaut 42 (somme des rangs de ses lettres dans l'alphabet). Combien vaut MIEL ?",o:["37","40","41","39"],a:3,e:"M (13) + I (9) + E (5) + L (12) = 39.",s:"Banque logique"},
{id:"lo2-054",t:"log",q:"Chaque lettre a un prix fixe. LOT coûte 12 €, LOTO 16 € et MOT 11 €. Combien coûte MOTO ?",o:["15 €","14 €","16 €","17 €"],a:0,e:"LOTO − LOT donne O = 4 € ; MOTO = MOT + O = 11 + 4 = 15 €.",s:"Banque logique"},
{id:"lo2-055",t:"log",q:"Chaque lettre a un prix fixe. PAIN coûte 20 €, PAINS 23 € et PIN 15 €. Combien coûte SAPIN ?",o:["21 €","23 €","22 €","25 €"],a:1,e:"SAPIN s'écrit avec exactement les lettres de PAINS : 23 €. Par le calcul : S = 3, A = 5, donc SAPIN = 3 + 5 + 15.",s:"Banque logique"},
{id:"lo2-056",t:"log",q:"Chaque lettre a un prix fixe. TOUR coûte 40 €, ROUTE 47 €, OURS 38 € et TOUT 44 €. Combien coûte SOUTE ?",o:["45 €","47 €","49 €","51 €"],a:2,e:"ROUTE − TOUR donne E = 7 ; OURS − TOUR donne S − T = −2 ; TOUT − TOUR donne T − R = 4. SOUTE = TOUR + E + S − R = 40 + 7 + 2 = 49 €.",s:"Banque logique"},
{id:"lo2-057",t:"log",q:"Dans un code, LIVRE s'écrit ILRVE. Comment s'écrit CAHIER ?",o:["ACHIER","CAIHER","REIHAC","ACIHRE"],a:3,e:"On permute les lettres deux à deux : LI → IL, VR → RV, E reste ; CA → AC, HI → IH, ER → RE.",s:"Banque logique"},
{id:"lo2-058",t:"log",q:"Si BOIS s'écrit YLRH, comment s'écrit FER ?",o:["UVI","GFS","UWI","VUI"],a:0,e:"Chaque lettre est remplacée par sa symétrique dans l'alphabet (A ↔ Z, B ↔ Y…), les deux rangs faisant 27 : F (6) → U (21), E (5) → V (22), R (18) → I (9).",s:"Banque logique"},
{id:"lo2-059",t:"log",q:"Dans un code, A = 26, B = 25, …, Z = 1. Quelle est la valeur du mot CODE (somme des valeurs de ses lettres) ?",o:["79","81","83","85"],a:1,e:"Valeur = 27 − rang : C 24 + O 12 + D 23 + E 22 = 81.",s:"Banque logique"},
{id:"lo2-060",t:"log",q:"Dans un jeu, chaque voyelle vaut 3 points et chaque consonne 2 points. Combien vaut le mot CONTRIBUABLE ?",o:["27","28","29","31"],a:2,e:"5 voyelles (O, I, U, A, E) font 15 points et 7 consonnes (C, N, T, R, B, B, L) font 14 points : 29.",s:"Banque logique"},
{id:"lo2-061",t:"log",q:"Si 5 + 3 = 28, 9 + 1 = 810 et 8 + 6 = 214, combien font 7 + 3 ?",o:["104","421","1 004","410"],a:3,e:"On écrit la différence puis la somme : 5 − 3 = 2 et 5 + 3 = 8 donnent 28 ; 7 − 3 = 4 et 7 + 3 = 10 donnent 410.",s:"Banque logique"},
// --- Calendriers ---
{id:"lo2-062",t:"log",q:"Nous sommes samedi. Quel jour serons-nous dans 1 000 jours ?",o:["Vendredi","Jeudi","Samedi","Dimanche"],a:0,e:"1 000 = 142 × 7 + 6 : samedi + 6 jours = vendredi.",s:"Banque logique"},
{id:"lo2-063",t:"log",q:"Laquelle de ces années est bissextile ?",o:["1900","2000","2100","2200"],a:1,e:"Une année séculaire n'est bissextile que si elle est divisible par 400 : 2000 l'est, pas 1900, 2100 ni 2200.",s:"Banque logique"},
{id:"lo2-064",t:"log",q:"Combien y a-t-il d'années bissextiles de 2001 à 2100 inclus ?",o:["23","25","24","26"],a:2,e:"Il y a 25 multiples de 4 de 2004 à 2100, mais 2100 n'est pas bissextile (non divisible par 400) : 24.",s:"Banque logique"},
{id:"lo2-065",t:"log",q:"Le 1er janvier 2024, année bissextile, était un lundi. Quel jour était le 1er janvier 2025 ?",o:["Mardi","Jeudi","Lundi","Mercredi"],a:3,e:"366 jours = 52 semaines + 2 jours : lundi + 2 = mercredi.",s:"Banque logique"},
{id:"lo2-066",t:"log",q:"Le 14 juillet 2026 est un mardi. Quel jour de la semaine sera le 14 juillet 2027 ?",o:["Mercredi","Mardi","Jeudi","Lundi"],a:0,e:"Entre les deux dates il y a 365 jours (février 2027 n'a que 28 jours), soit 52 semaines + 1 jour : mercredi.",s:"Banque logique"},
{id:"lo2-067",t:"log",q:"Quelle date sera-t-on 100 jours après le 1er mars ?",o:["8 juin","9 juin","10 juin","11 juin"],a:1,e:"30 jours jusqu'au 31 mars, 30 en avril, 31 en mai : 91 jours mènent au 31 mai ; 9 de plus : 9 juin.",s:"Banque logique"},
{id:"lo2-068",t:"log",q:"Un mois de 31 jours commence un vendredi. Quel jour de la semaine tombe le 31 ?",o:["Samedi","Lundi","Dimanche","Vendredi"],a:2,e:"Le 29 est un vendredi (1 + 28 jours) ; le 30 est un samedi et le 31 un dimanche.",s:"Banque logique"},
{id:"lo2-069",t:"log",q:"Combien une même année peut-elle compter, au maximum, de vendredis 13 ?",o:["2","4","5","3"],a:3,e:"Au plus trois mois d'une même année ont leur 13 le même jour de la semaine : c'est le cas en 2026 (février, mars et novembre).",s:"Banque logique"},
{id:"lo2-070",t:"log",q:"Si le surlendemain de demain est un jeudi, quel jour était avant-hier ?",o:["Samedi","Vendredi","Dimanche","Mardi"],a:0,e:"Le surlendemain de demain tombe dans 3 jours : aujourd'hui est lundi, donc avant-hier était samedi.",s:"Banque logique"},
{id:"lo2-071",t:"log",q:"Le 1er mars d'une année non bissextile est un mercredi. Quel jour était le 1er février de cette année ?",o:["Mardi","Mercredi","Jeudi","Samedi"],a:1,e:"Février compte 28 jours, soit exactement 4 semaines : le 1er février était aussi un mercredi.",s:"Banque logique"},
{id:"lo2-072",t:"log",q:"Le 31 décembre 2026 est un jeudi. Quel jour était le 1er janvier 2026 ?",o:["Mercredi","Vendredi","Jeudi","Samedi"],a:2,e:"2026 n'est pas bissextile : le 31 décembre est 364 jours (52 semaines) après le 1er janvier, c'était donc aussi un jeudi.",s:"Banque logique"},
{id:"lo2-073",t:"log",q:"Le 16 octobre 2026 est un vendredi. Quel jour de la semaine était le 16 octobre 2020 ?",o:["Mercredi","Jeudi","Samedi","Vendredi"],a:3,e:"Six années dont un 29 février (2024) : 6 × 365 + 1 = 2 191 jours, soit 313 semaines exactement : c'était aussi un vendredi.",s:"Banque logique"},
// --- Horloges et heures ---
{id:"lo2-074",t:"log",q:"Quel est le plus petit angle formé par les aiguilles d'une horloge à 4 h 00 ?",o:["120°","100°","110°","135°"],a:0,e:"Chaque heure du cadran correspond à 30° : 4 × 30° = 120°.",s:"Banque logique"},
{id:"lo2-075",t:"log",q:"Quel est le plus petit angle formé par les aiguilles d'une horloge à 2 h 20 ?",o:["40°","50°","60°","70°"],a:1,e:"Petite aiguille : 2 × 30 + 20 × 0,5 = 70° ; grande aiguille : 20 × 6 = 120° ; écart : 50°.",s:"Banque logique"},
{id:"lo2-076",t:"log",q:"Quel est le plus petit angle formé par les aiguilles d'une horloge à 7 h 30 ?",o:["30°","60°","45°","75°"],a:2,e:"Petite aiguille : 7,5 × 30 = 225° ; grande aiguille : 180° ; écart : 45°.",s:"Banque logique"},
{id:"lo2-077",t:"log",q:"Quel est le plus petit angle formé par les aiguilles d'une horloge à 10 h 15 ?",o:["135°","150°","157,5°","142,5°"],a:3,e:"Petite aiguille : 10 × 30 + 15 × 0,5 = 307,5° ; grande : 90° ; écart 217,5°, soit 360 − 217,5 = 142,5°.",s:"Banque logique"},
{id:"lo2-078",t:"log",q:"Entre 3 h et 4 h, à quel instant (à la seconde près) les deux aiguilles d'une horloge sont-elles superposées ?",o:["3 h 16 min 22 s","3 h 15 min 00 s","3 h 17 min 10 s","3 h 18 min 00 s"],a:0,e:"La grande aiguille rattrape 5,5° par minute sur la petite, qui a 90° d'avance : 90 / 5,5 ≈ 16,36 min, soit 3 h 16 min 22 s.",s:"Banque logique"},
{id:"lo2-079",t:"log",q:"Il est 14 h à Paris (UTC+1). Quelle heure est-il au même instant à New York (UTC−5) ?",o:["9 h","8 h","19 h","20 h"],a:1,e:"Six heures d'écart, New York étant en retard : 14 − 6 = 8 h.",s:"Banque logique"},
{id:"lo2-080",t:"log",q:"Un avion quitte Paris à 10 h (heure de Paris) pour Montréal, qui a 6 heures de retard sur Paris. Le vol dure 7 h 30. Quelle heure locale est-il à l'arrivée ?",o:["12 h 30","17 h 30","11 h 30","23 h 30"],a:2,e:"Arrivée à 17 h 30, heure de Paris, soit 17 h 30 − 6 h = 11 h 30 à Montréal.",s:"Banque logique"},
{id:"lo2-081",t:"log",q:"Un avion quitte Tokyo à 22 h (heure locale) et arrive à Paris à 5 h le lendemain (heure de Paris). Tokyo a 8 heures d'avance sur Paris. Combien de temps a duré le vol ?",o:["7 h","13 h","17 h","15 h"],a:3,e:"Le départ a lieu à 22 h − 8 h = 14 h, heure de Paris ; de 14 h à 5 h le lendemain : 15 heures.",s:"Banque logique"},
{id:"lo2-082",t:"log",q:"Vue dans un miroir, une horloge à aiguilles sans chiffres semble indiquer 3 h 15. Quelle heure est-il réellement ?",o:["8 h 45","9 h 45","9 h 15","8 h 15"],a:0,e:"Le miroir inverse la gauche et la droite : heure réelle = 12 h 00 − 3 h 15 = 8 h 45.",s:"Banque logique"},
{id:"lo2-083",t:"log",q:"Un agent commence à 8 h 47 et termine à 17 h 12, avec une pause de 1 h 15. Combien de temps a-t-il travaillé ?",o:["7 h 25","7 h 10","7 h 35","8 h 25"],a:1,e:"De 8 h 47 à 17 h 12 : 8 h 25 ; moins 1 h 15 de pause : 7 h 10.",s:"Banque logique"},
{id:"lo2-084",t:"log",q:"Quand il est midi à Londres (UTC), il est 21 h à Tokyo. Quelle heure est-il à Tokyo lorsqu'il est 18 h à Paris (UTC+1) ?",o:["1 h","3 h","2 h","9 h"],a:2,e:"18 h à Paris correspond à 17 h UTC ; Tokyo a 9 heures d'avance sur UTC : 2 h du matin, le lendemain.",s:"Banque logique"},
// --- Probabilités ---
{id:"lo2-085",t:"log",q:"On lance un dé équilibré à six faces. Quelle est la probabilité d'obtenir un nombre pair ?",o:["1/6","1/3","2/3","1/2"],a:3,e:"3 cas favorables (2, 4, 6) sur 6 : 1/2.",s:"Banque logique"},
{id:"lo2-086",t:"log",q:"On lance deux dés équilibrés. Quelle est la probabilité que la somme soit égale à 10 ?",o:["1/12","1/18","1/9","1/6"],a:0,e:"3 cas sur 36 : (4,6), (5,5), (6,4), soit 1/12.",s:"Banque logique"},
{id:"lo2-087",t:"log",q:"On lance deux dés équilibrés. Quelle est la probabilité d'obtenir au moins un 6 ?",o:["1/6","11/36","1/3","5/18"],a:1,e:"Événement contraire (aucun 6) : (5/6)² = 25/36 ; donc 1 − 25/36 = 11/36.",s:"Banque logique"},
{id:"lo2-088",t:"log",q:"On tire une carte d'un jeu de 32 cartes. Quelle est la probabilité de tirer un as ?",o:["1/4","1/13","1/8","1/32"],a:2,e:"4 as sur 32 cartes : 1/8.",s:"Banque logique"},
{id:"lo2-089",t:"log",q:"On tire une carte d'un jeu de 52 cartes. Quelle est la probabilité de tirer un cœur ou un roi ?",o:["1/4","17/52","5/13","4/13"],a:3,e:"13 cœurs + 4 rois − le roi de cœur compté deux fois = 16 cartes : 16/52 = 4/13.",s:"Banque logique"},
{id:"lo2-090",t:"log",q:"On tire une carte d'un jeu de 52 cartes. Quelle est la probabilité de tirer une figure (valet, dame ou roi) ?",o:["3/13","1/13","4/13","1/4"],a:0,e:"12 figures sur 52 cartes : 12/52 = 3/13.",s:"Banque logique"},
{id:"lo2-091",t:"log",q:"Une urne contient 3 boules rouges et 2 bleues. On tire deux boules sans remise. Quelle est la probabilité qu'elles soient toutes les deux rouges ?",o:["1/5","3/10","9/25","2/5"],a:1,e:"3/5 pour la première, puis 2/4 pour la seconde : 3/5 × 2/4 = 3/10.",s:"Banque logique"},
{id:"lo2-092",t:"log",q:"On lance trois pièces équilibrées. Quelle est la probabilité d'obtenir exactement deux « pile » ?",o:["1/4","1/2","3/8","2/3"],a:2,e:"8 issues équiprobables, dont 3 avec exactement deux « pile » (PPF, PFP, FPP) : 3/8.",s:"Banque logique"},
{id:"lo2-093",t:"log",q:"On lance deux dés équilibrés. Quelle est la probabilité que la somme soit inférieure ou égale à 4 ?",o:["1/9","2/9","1/4","1/6"],a:3,e:"Somme 2 : 1 cas ; somme 3 : 2 cas ; somme 4 : 3 cas. 6 cas sur 36 = 1/6.",s:"Banque logique"},
{id:"lo2-094",t:"log",q:"Dans un groupe de 20 personnes, 12 parlent anglais, 8 espagnol et 5 les deux langues. Quelle est la probabilité qu'une personne choisie au hasard ne parle aucune des deux ?",o:["25 %","20 %","30 %","0 %"],a:0,e:"12 + 8 − 5 = 15 personnes parlent au moins une des deux langues ; 5 sur 20 n'en parlent aucune : 25 %.",s:"Banque logique"},
{id:"lo2-095",t:"log",q:"On tire au hasard une lettre du mot PROBABILITE. Quelle est la probabilité de tirer un B ?",o:["1/11","2/11","3/11","1/5"],a:1,e:"Le mot compte 11 lettres, dont 2 B : 2/11.",s:"Banque logique"},
{id:"lo2-096",t:"log",q:"On lance deux dés équilibrés. Quelle est la probabilité que le produit des deux résultats soit pair ?",o:["1/2","2/3","3/4","5/6"],a:2,e:"Le produit n'est impair que si les deux dés sont impairs : 1/2 × 1/2 = 1/4. Il est donc pair avec la probabilité 3/4.",s:"Banque logique"},
{id:"lo2-097",t:"log",q:"À un jeu, on lance un dé : on gagne 10 € si l'on obtient 6, sinon on perd 1 €. Quel est le gain moyen par partie ?",o:["−1 €","0 €","Environ 1,67 €","Environ 0,83 €"],a:3,e:"Espérance : 10 × 1/6 − 1 × 5/6 = 5/6, soit environ 0,83 €.",s:"Banque logique"},
// --- Dénombrement ---
{id:"lo2-098",t:"log",q:"Huit personnes se serrent toutes la main, une fois chacune avec chacune. Combien y a-t-il de poignées de main ?",o:["28","16","56","64"],a:0,e:"8 × 7 / 2 = 28 (chaque poignée de main concerne deux personnes).",s:"Banque logique"},
{id:"lo2-099",t:"log",q:"Un menu propose 3 entrées, 4 plats et 2 desserts. Combien de menus « entrée-plat-dessert » différents peut-on composer ?",o:["9","24","12","36"],a:1,e:"Principe multiplicatif : 3 × 4 × 2 = 24.",s:"Banque logique"},
{id:"lo2-100",t:"log",q:"De combien de façons 5 personnes peuvent-elles s'asseoir sur un banc de 5 places ?",o:["25","60","120","720"],a:2,e:"5 × 4 × 3 × 2 × 1 = 120.",s:"Banque logique"},
{id:"lo2-101",t:"log",q:"Combien de « mots » différents (ayant un sens ou non) peut-on écrire en utilisant toutes les lettres de RADAR ?",o:["15","60","120","30"],a:3,e:"5! / (2! × 2!) = 120 / 4 = 30, car le mot contient deux R et deux A.",s:"Banque logique"},
{id:"lo2-102",t:"log",q:"On choisit 2 personnes parmi 6 pour former un binôme. Combien de binômes différents est-il possible de former ?",o:["15","12","30","36"],a:0,e:"6 × 5 / 2 = 15 (l'ordre des deux personnes ne compte pas).",s:"Banque logique"},
{id:"lo2-103",t:"log",q:"Parmi 6 personnes, on désigne un président et un trésorier, qui doivent être différents. Combien de choix possibles ?",o:["15","30","12","36"],a:1,e:"6 choix pour le président, puis 5 pour le trésorier : 30 (ici l'ordre compte).",s:"Banque logique"},
{id:"lo2-104",t:"log",q:"Combien d'entiers de 1 à 100 sont divisibles par 3 ou par 5 ?",o:["45","50","47","53"],a:2,e:"33 multiples de 3 + 20 multiples de 5 − 6 multiples de 15 (comptés deux fois) = 47.",s:"Banque logique"},
{id:"lo2-105",t:"log",q:"Combien de chiffres faut-il écrire pour numéroter les pages d'un livre de la page 1 à la page 120 ?",o:["240","260","360","252"],a:3,e:"9 pages à 1 chiffre + 90 pages à 2 chiffres + 21 pages à 3 chiffres : 9 + 180 + 63 = 252.",s:"Banque logique"},
{id:"lo2-106",t:"log",q:"Combien de fois le chiffre 7 apparaît-il quand on écrit tous les nombres de 1 à 100 ?",o:["20","10","11","19"],a:0,e:"10 fois au rang des unités (7, 17… 97) et 10 fois au rang des dizaines (70 à 79) : 20, le 77 comptant deux fois.",s:"Banque logique"},
{id:"lo2-107",t:"log",q:"Un tiroir contient 10 chaussettes noires et 10 blanches, mélangées. Combien faut-il en prendre au minimum, sans regarder, pour être sûr d'en avoir deux de la même couleur ?",o:["2","3","11","20"],a:1,e:"Avec deux couleurs seulement, trois chaussettes garantissent qu'au moins deux sont de la même couleur.",s:"Banque logique"},
{id:"lo2-108",t:"log",q:"Un tournoi à élimination directe réunit 16 équipes. Combien de matchs faut-il jouer pour désigner le vainqueur ?",o:["8","16","15","31"],a:2,e:"Chaque match élimine une équipe ; il faut en éliminer 15 : 15 matchs (8 + 4 + 2 + 1).",s:"Banque logique"},
// --- Liens de parenté ---
{id:"lo2-109",t:"log",q:"Le frère de la mère de mon père est mon :",o:["Oncle","Cousin","Arrière-grand-père","Grand-oncle"],a:3,e:"La mère de mon père est ma grand-mère ; son frère est mon grand-oncle.",s:"Banque logique"},
{id:"lo2-110",t:"log",q:"La fille de la sœur de ma mère est ma :",o:["Cousine","Nièce","Tante","Sœur"],a:0,e:"La sœur de ma mère est ma tante ; sa fille est ma cousine.",s:"Banque logique"},
{id:"lo2-111",t:"log",q:"Le fils de ma sœur est mon :",o:["Cousin","Neveu","Oncle","Petit-fils"],a:1,e:"L'enfant d'un frère ou d'une sœur est un neveu ou une nièce.",s:"Banque logique"},
{id:"lo2-112",t:"log",q:"Je n'ai ni frère ni sœur. Le père de cet homme est le fils de mon père. Qui est cet homme ?",o:["Moi-même","Mon père","Mon fils","Mon neveu"],a:2,e:"Le fils de mon père, puisque je n'ai pas de frère, c'est moi ; je suis donc le père de cet homme : c'est mon fils.",s:"Banque logique"},
{id:"lo2-113",t:"log",q:"La mère du père de ma mère est ma :",o:["Grand-mère","Grand-tante","Arrière-arrière-grand-mère","Arrière-grand-mère"],a:3,e:"Le père de ma mère est mon grand-père ; sa mère est mon arrière-grand-mère.",s:"Banque logique"},
{id:"lo2-114",t:"log",q:"Anne est la fille de Bernard. Bernard est le fils de Claire. Claire est la sœur de Denis. Qu'est Denis pour Anne ?",o:["Son grand-oncle","Son oncle","Son grand-père","Son cousin"],a:0,e:"Denis est le frère de la mère de Bernard, donc l'oncle de Bernard, et le grand-oncle d'Anne.",s:"Banque logique"},
{id:"lo2-115",t:"log",q:"Luc est le père de Marc, qui est le père de Jules. Sophie est la sœur de Marc. Qu'est Sophie pour Jules ?",o:["Sa cousine","Sa tante","Sa sœur","Sa grand-mère"],a:1,e:"Sophie est la sœur du père de Jules : c'est sa tante.",s:"Banque logique"},
{id:"lo2-116",t:"log",q:"Sans ancêtre commun, combien une personne a-t-elle au total de grands-parents, d'arrière-grands-parents et d'arrière-arrière-grands-parents ?",o:["14","24","28","30"],a:2,e:"Le nombre d'ancêtres double à chaque génération : 4 + 8 + 16 = 28.",s:"Banque logique"},
{id:"lo2-117",t:"log",q:"Une femme montre la photo d'un homme et dit : « Sa mère est la fille unique de ma mère. » Qui est cet homme pour elle ?",o:["Son frère","Son neveu","Son père","Son fils"],a:3,e:"La fille unique de sa mère, c'est elle-même ; elle est la mère de l'homme : c'est son fils.",s:"Banque logique"},
{id:"lo2-118",t:"log",q:"La sœur de ma mère a un fils. Pour ce garçon, ma mère est sa :",o:["Tante","Cousine","Grand-mère","Sœur"],a:0,e:"Ma mère est la sœur de la mère de ce garçon : elle est sa tante.",s:"Banque logique"},
// --- Syllogismes et déductions ---
{id:"lo2-119",t:"log",q:"Aucun poisson n'est un mammifère. Le saumon est un poisson. Que peut-on conclure ?",o:["Le saumon est un mammifère","Le saumon n'est pas un mammifère","Certains mammifères sont des saumons","On ne peut rien conclure"],a:1,e:"Le saumon appartient à l'ensemble des poissons, qui n'a aucun élément commun avec celui des mammifères.",s:"Banque logique"},
{id:"lo2-120",t:"log",q:"Certains fonctionnaires sont inspecteurs. Tous les inspecteurs ont réussi un concours. Que peut-on conclure ?",o:["Tous les fonctionnaires ont réussi un concours","Aucun fonctionnaire n'a réussi de concours","Certains fonctionnaires ont réussi un concours","Tous les lauréats d'un concours sont inspecteurs"],a:2,e:"Les fonctionnaires qui sont inspecteurs ont réussi un concours ; rien n'est dit des autres.",s:"Banque logique"},
{id:"lo2-121",t:"log",q:"S'il pleut, la route est mouillée. La route est mouillée. Que peut-on conclure ?",o:["Il pleut","Il ne pleut pas","Il a plu dans la nuit","On ne peut pas savoir s'il pleut"],a:3,e:"La route peut être mouillée pour une autre raison : on ne remonte pas de la conséquence à la condition.",s:"Banque logique"},
{id:"lo2-122",t:"log",q:"Quelle est la négation de « Tous les agents sont présents » ?",o:["Au moins un agent est absent","Tous les agents sont absents","Aucun agent n'est présent","Au moins un agent est présent"],a:0,e:"Nier « tous » revient à affirmer qu'il existe au moins une exception.",s:"Banque logique"},
{id:"lo2-123",t:"log",q:"Quelle est la négation de « Il pleut et il fait froid » ?",o:["Il ne pleut pas et il ne fait pas froid","Il ne pleut pas ou il ne fait pas froid","Il pleut ou il fait froid","Il ne pleut pas et il fait froid"],a:1,e:"La négation de « A et B » est « non A ou non B » : il suffit que l'une des deux conditions manque.",s:"Banque logique"},
{id:"lo2-124",t:"log",q:"Tous les A sont des B. Aucun B n'est un C. Que peut-on conclure ?",o:["Certains A sont des C","Tous les C sont des A","Aucun A n'est un C","Certains C sont des B"],a:2,e:"Les A sont inclus dans les B, qui n'ont aucun élément commun avec les C.",s:"Banque logique"},
{id:"lo2-125",t:"log",q:"Seuls les agents habilités peuvent consulter ce fichier. Léa l'a consulté. Que peut-on conclure ?",o:["Léa n'est pas habilitée","Tous les agents habilités l'ont consulté","On ne peut rien conclure","Léa est habilitée"],a:3,e:"« Seuls les habilités peuvent consulter » signifie : avoir consulté implique être habilité.",s:"Banque logique"},
{id:"lo2-126",t:"log",q:"Si Marc vient, Julie vient. Si Julie vient, Paul ne vient pas. Or Paul vient. Que peut-on conclure ?",o:["Ni Marc ni Julie ne viennent","Marc et Julie viennent","Julie vient mais pas Marc","Marc vient mais pas Julie"],a:0,e:"Paul vient, donc Julie ne vient pas (contraposée) ; Julie ne venant pas, Marc ne vient pas non plus.",s:"Banque logique"},
{id:"lo2-127",t:"log",q:"Tous les membres du club sont musiciens. Certains musiciens sont sportifs. Jean est sportif. Que peut-on affirmer avec certitude ?",o:["Jean est membre du club","On ne peut pas savoir si Jean est membre du club","Jean est musicien","Jean n'est pas membre du club"],a:1,e:"Être sportif n'implique ni d'être musicien ni d'être membre du club : aucune des trois autres affirmations n'est certaine.",s:"Banque logique"},
{id:"lo2-128",t:"log",q:"Quelle phrase est équivalente à « Si je réussis, je suis content » ?",o:["Si je suis content, j'ai réussi","Si je ne réussis pas, je ne suis pas content","Si je ne suis pas content, je n'ai pas réussi","Je réussis et je suis content"],a:2,e:"Une implication « A ⇒ B » équivaut à sa contraposée « non B ⇒ non A ».",s:"Banque logique"},
{id:"lo2-129",t:"log",q:"Quelle est la négation de « Certains candidats ont échoué » ?",o:["Certains candidats ont réussi","Tous les candidats ont échoué","Certains candidats n'ont pas échoué","Aucun candidat n'a échoué"],a:3,e:"Nier « il en existe au moins un » revient à dire « il n'en existe aucun ».",s:"Banque logique"},
{id:"lo2-130",t:"log",q:"Aucun inspecteur n'est stagiaire. Certains stagiaires sont diplômés. Que peut-on conclure ?",o:["Certains diplômés ne sont pas inspecteurs","Aucun diplômé n'est inspecteur","Certains inspecteurs sont diplômés","Tous les diplômés sont stagiaires"],a:0,e:"Les stagiaires diplômés existent et ne sont pas inspecteurs : certains diplômés ne sont donc pas inspecteurs.",s:"Banque logique"},
// --- Vrai ou faux, menteurs ---
{id:"lo2-131",t:"log",q:"Chacun ment toujours ou dit toujours la vérité. Anne dit : « Basile ment. » Basile dit : « Chloé ment. » Chloé dit : « Anne et Basile mentent. » Qui dit la vérité ?",o:["Anne seule","Basile seul","Chloé seule","Anne et Chloé"],a:1,e:"Si Anne disait vrai, Basile mentirait, Chloé dirait vrai et Anne mentirait : contradiction. Donc Anne ment, Basile dit vrai, Chloé ment (sa phrase est bien fausse).",s:"Banque logique"},
{id:"lo2-132",t:"log",q:"Sur une île, les chevaliers disent toujours la vérité et les fripons mentent toujours. A déclare : « B et moi sommes deux fripons. » Que sont A et B ?",o:["Deux chevaliers","Deux fripons","A fripon, B chevalier","A chevalier, B fripon"],a:2,e:"Un chevalier ne peut pas se dire fripon : A est fripon, sa phrase est fausse, donc B n'est pas fripon.",s:"Banque logique"},
{id:"lo2-133",t:"log",q:"Un trésor est caché dans une seule des boîtes A, B, C ou D. Une seule de ces phrases est vraie : (1) le trésor est dans A ; (2) le trésor n'est pas dans B ; (3) le trésor n'est pas dans A. Où est le trésor ?",o:["A","C","D","B"],a:3,e:"(1) et (3) se contredisent, donc l'une d'elles est la phrase vraie ; (2) est alors fausse : le trésor est dans B.",s:"Banque logique"},
{id:"lo2-134",t:"log",q:"Un seul des quatre suspects dit la vérité, et un seul est coupable. Alain : « C'est Brigitte. » Brigitte : « C'est Diane. » Cédric : « Ce n'est pas moi. » Diane : « Brigitte ment. » Qui est coupable ?",o:["Cédric","Alain","Brigitte","Diane"],a:0,e:"On teste chaque coupable possible : seul le cas « Cédric » donne exactement une phrase vraie (celle de Diane).",s:"Banque logique"},
{id:"lo2-135",t:"log",q:"Paul ment toujours. Il affirme : « Je n'ai pas de voiture et j'ai un vélo. » Que peut-on en déduire ?",o:["Il a une voiture et pas de vélo","Il a une voiture ou il n'a pas de vélo","Il n'a ni voiture ni vélo","Il a une voiture et un vélo"],a:1,e:"Sa phrase est fausse ; la négation de « non A et B » est « A ou non B ».",s:"Banque logique"},
{id:"lo2-136",t:"log",q:"Trois boîtes portent les étiquettes « Pommes », « Poires » et « Mélange », toutes fausses. On tire un fruit de la boîte « Mélange » : c'est une pomme. Que contient la boîte étiquetée « Poires » ?",o:["Des pommes","Des poires","Le mélange","On ne peut pas savoir"],a:2,e:"La boîte « Mélange » ne contient pas le mélange : ce sont des pommes. La boîte « Poires » ne contient ni poires ni pommes : c'est le mélange.",s:"Banque logique"},
{id:"lo2-137",t:"log",q:"Dans quel cas l'affirmation « S'il fait beau, je sors » est-elle fausse ?",o:["Il fait beau et je sors","Il ne fait pas beau et je sors","Il ne fait pas beau et je ne sors pas","Il fait beau et je ne sors pas"],a:3,e:"Une implication n'est fausse que lorsque la condition est remplie et que la conséquence n'a pas lieu.",s:"Banque logique"},
{id:"lo2-138",t:"log",q:"Un entier N compris entre 1 et 30 vérifie exactement trois des quatre affirmations suivantes : (1) N est pair ; (2) N est multiple de 7 ; (3) N est supérieur à 20 ; (4) N est un carré parfait. Que vaut N ?",o:["28","14","21","25"],a:0,e:"Aucun carré de 1 à 30 ne vérifie deux autres affirmations ; il faut donc (1), (2) et (3) : N pair, multiple de 7 et supérieur à 20, soit 28.",s:"Banque logique"},
// --- Classements et ordonnancement ---
{id:"lo2-139",t:"log",q:"Cinq coureurs. Bruno arrive juste après Alice ; David arrive avant Alice ; Chloé n'est ni première ni dernière ; Emma arrive après Chloé mais n'est pas dernière. Qui est arrivé 3e ?",o:["Alice","Emma","Chloé","David"],a:1,e:"Emma n'étant pas dernière, le dernier est Bruno (juste après Alice) ; on obtient David, Chloé, Emma, Alice, Bruno.",s:"Banque logique"},
{id:"lo2-140",t:"log",q:"Un immeuble de cinq étages compte un habitant par étage. Carl habite au 3e, Elie au 1er ; Ana habite plus haut que Ben ; Dora habite juste en dessous d'Ana. À quel étage habite Ben ?",o:["Au 4e","Au 5e","Au 2e","Au 3e"],a:2,e:"Restent les étages 2, 4 et 5 ; Dora juste sous Ana impose Ana au 5e et Dora au 4e : Ben est au 2e.",s:"Banque logique"},
{id:"lo2-141",t:"log",q:"Anne est plus âgée que Bruno mais plus jeune que Carla. Didier est plus âgé que Carla. Qui est le plus âgé ?",o:["Anne","Bruno","Carla","Didier"],a:3,e:"Du plus jeune au plus âgé : Bruno, Anne, Carla, Didier.",s:"Banque logique"},
{id:"lo2-142",t:"log",q:"Dans une file d'attente, Paul est le 7e en partant de l'avant et le 12e en partant de l'arrière. Combien de personnes compte la file ?",o:["18","17","19","20"],a:0,e:"7 + 12 − 1 = 18, car Paul est compté deux fois.",s:"Banque logique"},
{id:"lo2-143",t:"log",q:"A pèse plus que B ; C pèse moins que B ; D pèse plus que A. Quel est l'ordre du plus léger au plus lourd ?",o:["C, A, B, D","C, B, A, D","B, C, A, D","D, A, B, C"],a:1,e:"C est plus léger que B, B plus léger que A, et A plus léger que D : C, B, A, D.",s:"Banque logique"},
{id:"lo2-144",t:"log",q:"Cinq réunions R1 à R5 se tiennent du lundi au vendredi, une par jour. R1 a lieu mercredi ; R2 a lieu la veille de R4 ; R5 a lieu avant R3 ; R3 n'a pas lieu le vendredi. Quel jour a lieu R3 ?",o:["Lundi","Jeudi","Mardi","Vendredi"],a:2,e:"Si R2 et R4 étaient lundi et mardi, R3 (exclu du vendredi) serait jeudi et R5 vendredi, après R3 : impossible. Donc R2 jeudi, R4 vendredi, R5 lundi et R3 mardi.",s:"Banque logique"},
{id:"lo2-145",t:"log",q:"Dans une course, je double le deuxième. Quelle est alors ma place ?",o:["Premier","Troisième","Avant-dernier","Deuxième"],a:3,e:"Je prends la place de celui que je viens de doubler : la deuxième.",s:"Banque logique"},
{id:"lo2-146",t:"log",q:"Dans une course à cinq, Ana termine devant Bob mais derrière Chloé ; Dan termine derrière Bob ; Eve termine entre Chloé et Ana. Qui termine 3e ?",o:["Ana","Eve","Bob","Chloé"],a:0,e:"Chloé devance Ana, qui devance Bob, qui devance Dan ; Eve s'intercale entre Chloé et Ana : Chloé, Eve, Ana, Bob, Dan.",s:"Banque logique"},
{id:"lo2-147",t:"log",q:"Ali, Béa, Cyril et Dina travaillent à l'accueil, au contrôle, au recouvrement et au cadastre (un par service). Ali n'est ni à l'accueil ni au cadastre ; Béa n'est ni au contrôle ni à l'accueil ; Cyril n'est ni au contrôle ni au recouvrement ; Dina n'est ni au cadastre, ni au recouvrement, ni au contrôle. Qui est au recouvrement ?",o:["Ali","Béa","Cyril","Dina"],a:1,e:"Dina est à l'accueil, donc Cyril au cadastre, Béa au recouvrement et Ali au contrôle.",s:"Banque logique"},
{id:"lo2-148",t:"log",q:"Léo, Mia, Noé et Zoé sont assis sur un banc de quatre places. Noé n'est à aucune extrémité ; Mia est à la droite de Léo (pas forcément à côté) ; Zoé est à côté de Léo mais pas à l'extrémité gauche. Qui est en 2e position en partant de la gauche ?",o:["Léo","Mia","Noé","Zoé"],a:3,e:"Seul ordre possible de gauche à droite : Léo, Zoé, Noé, Mia.",s:"Banque logique"},
// --- Problèmes arithmétiques ---
{id:"lo2-149",t:"log",q:"Une mère a 36 ans et sa fille 12 ans. Il y a combien d'années la mère avait-elle cinq fois l'âge de sa fille ?",o:["4","5","6","8"],a:2,e:"36 − x = 5 (12 − x) donne 4x = 24, soit x = 6 (elles avaient alors 30 ans et 6 ans).",s:"Banque logique"},
{id:"lo2-150",t:"log",q:"Dans 6 ans, Léo aura le triple de l'âge qu'il avait il y a 6 ans. Quel âge a-t-il ?",o:["9","15","18","12"],a:3,e:"x + 6 = 3 (x − 6) donne 2x = 24, soit x = 12.",s:"Banque logique"},
{id:"lo2-151",t:"log",q:"J'ai le double de l'âge que tu avais quand j'avais l'âge que tu as. Quand tu auras mon âge, la somme de nos âges sera de 63 ans. Quel âge ai-je ?",o:["28","21","24","32"],a:0,e:"Avec x (moi) et y (toi) : x = 2 (2y − x), soit 3x = 4y ; puis x + (2x − y) = 63. D'où x = 28 et y = 21.",s:"Banque logique"},
{id:"lo2-152",t:"log",q:"On partage 360 € entre trois personnes proportionnellement à 2, 3 et 4. Quel est le montant de la plus grosse part ?",o:["120 €","160 €","140 €","180 €"],a:1,e:"9 parts au total : 360 / 9 = 40 € la part ; 4 × 40 = 160 €.",s:"Banque logique"},
{id:"lo2-153",t:"log",q:"Un héritage est partagé ainsi : la moitié à l'aîné, le tiers au cadet, et le reste, soit 8 000 €, au benjamin. Quel est le montant de l'héritage ?",o:["40 000 €","56 000 €","48 000 €","64 000 €"],a:2,e:"Le benjamin reçoit 1 − 1/2 − 1/3 = 1/6 du total : 6 × 8 000 = 48 000 €.",s:"Banque logique"},
{id:"lo2-154",t:"log",q:"Un robinet remplit une cuve en 4 h ; une vidange ouverte la vide en 6 h. Les deux étant ouverts, en combien de temps la cuve vide se remplit-elle ?",o:["2 h","5 h","10 h","12 h"],a:3,e:"1/4 − 1/6 = 1/12 de cuve par heure : 12 heures.",s:"Banque logique"},
{id:"lo2-155",t:"log",q:"A fait seul un travail en 10 jours, B le fait seul en 15 jours. Ensemble, en combien de jours le font-ils ?",o:["6","5","12,5","25"],a:0,e:"1/10 + 1/15 = 1/6 du travail par jour : 6 jours.",s:"Banque logique"},
{id:"lo2-156",t:"log",q:"6 ouvriers fabriquent 6 tables en 6 jours. Combien de tables 12 ouvriers fabriquent-ils en 12 jours, au même rythme ?",o:["12","24","18","48"],a:1,e:"Un ouvrier fait une table en 6 jours ; 12 ouvriers pendant 12 jours : 12 × 12 / 6 = 24 tables.",s:"Banque logique"},
{id:"lo2-157",t:"log",q:"12 personnes doivent achever un chantier en 20 jours. Au bout de 5 jours, 3 personnes partent. Combien de jours faut-il au total pour achever le chantier ?",o:["20","23","25","27"],a:2,e:"Travail : 240 jours-personne ; 60 sont faits ; restent 180 pour 9 personnes, soit 20 jours : 5 + 20 = 25 jours.",s:"Banque logique"},
{id:"lo2-159",t:"log",q:"Deux trains partent au même moment de deux villes distantes de 300 km et roulent l'un vers l'autre, à 80 km/h et à 120 km/h. Au bout de combien de temps se croisent-ils ?",o:["1 h 30","1 h 15","1 h 45","2 h 30"],a:0,e:"Ils se rapprochent à 80 + 120 = 200 km/h : 300 / 200 = 1,5 h, soit 1 h 30.",s:"Banque logique"},
{id:"lo2-160",t:"log",q:"Un cycliste part à 9 h à 20 km/h. Une voiture part du même point à 10 h, sur la même route, à 60 km/h. À quelle heure le rattrape-t-elle ?",o:["10 h 20","10 h 30","10 h 40","11 h"],a:1,e:"À 10 h, le cycliste a 20 km d'avance ; la voiture regagne 40 km par heure : 20 / 40 = 0,5 h, soit 10 h 30.",s:"Banque logique"},
{id:"lo2-161",t:"log",q:"Un train de 200 m roule à 72 km/h et traverse un tunnel de 1 km. Combien de temps s'écoule entre l'entrée de la locomotive et la sortie du dernier wagon ?",o:["50 s","55 s","60 s","70 s"],a:2,e:"72 km/h = 20 m/s ; il faut parcourir 1 000 + 200 = 1 200 m, soit 60 s.",s:"Banque logique"},
{id:"lo2-162",t:"log",q:"Après une baisse de 20 %, de quel pourcentage un prix doit-il augmenter pour revenir à sa valeur initiale ?",o:["20 %","22,5 %","30 %","25 %"],a:3,e:"Il faut multiplier par 1 / 0,8 = 1,25, soit une hausse de 25 %.",s:"Banque logique"},
{id:"lo2-165",t:"log",q:"Un article à 200 € bénéficie d'une remise de 10 %, puis d'une remise supplémentaire de 5 % sur le prix remisé. Quel est le prix final ?",o:["170 €","172 €","171 €","175 €"],a:2,e:"200 × 0,9 × 0,95 = 171 € : des remises successives ne s'additionnent pas.",s:"Banque logique"},
{id:"lo2-166",t:"log",q:"Après une augmentation de 25 %, un salaire atteint 2 500 €. Quel était le salaire initial ?",o:["1 875 €","2 025 €","2 250 €","2 000 €"],a:3,e:"2 500 / 1,25 = 2 000 € (et non 2 500 × 0,75 = 1 875 €).",s:"Banque logique"},
{id:"lo2-167",t:"log",q:"On mélange 2 L de jus contenant 10 % de sucre avec 3 L de jus contenant 20 % de sucre. Quel est le taux de sucre du mélange ?",o:["16 %","14 %","15 %","18 %"],a:0,e:"Sucre : 0,2 + 0,6 = 0,8 L pour 5 L de mélange, soit 16 %.",s:"Banque logique"},
{id:"lo2-168",t:"log",q:"Combien de litres d'eau faut-il ajouter à 10 L d'une solution salée à 30 % pour obtenir une solution à 20 % ?",o:["2 L","5 L","10 L","15 L"],a:1,e:"La solution contient 3 L de sel ; 3 / (10 + x) = 0,2 donne 10 + x = 15, soit x = 5 L.",s:"Banque logique"},
{id:"lo2-169",t:"log",q:"Un café coûte 12 € le kilo, un autre 18 € le kilo. Dans quelles proportions faut-il les mélanger pour obtenir un café à 14 € le kilo ?",o:["1/3 de café à 12 € et 2/3 à 18 €","Moitié-moitié","2/3 de café à 12 € et 1/3 à 18 €","3/4 de café à 12 € et 1/4 à 18 €"],a:2,e:"12x + 18 (1 − x) = 14 donne 6x = 4, soit x = 2/3 de café à 12 €.",s:"Banque logique"},
{id:"lo2-170",t:"log",q:"Dans une basse-cour, on compte 20 têtes et 56 pattes, uniquement des poules et des lapins. Combien y a-t-il de lapins ?",o:["6","10","12","8"],a:3,e:"Si tous étaient des poules : 40 pattes ; les 16 pattes en plus, à raison de 2 par lapin, donnent 8 lapins.",s:"Banque logique"},
{id:"lo2-171",t:"log",q:"Un escargot grimpe un mur de 10 m : il monte de 3 m le jour et glisse de 2 m la nuit. Au cours de quel jour atteint-il le sommet ?",o:["Le 8e","Le 7e","Le 9e","Le 10e"],a:0,e:"Au matin du 8e jour, il est à 7 m ; il monte de 3 m dans la journée et atteint 10 m.",s:"Banque logique"},
{id:"lo2-172",t:"log",q:"Une bouteille et son bouchon coûtent 1,10 € ; la bouteille coûte 1 € de plus que le bouchon. Combien coûte le bouchon ?",o:["0,10 €","0,05 €","0,15 €","1,00 €"],a:1,e:"b + (b + 1) = 1,10 donne 2b = 0,10 : le bouchon coûte 0,05 €.",s:"Banque logique"},
{id:"lo2-173",t:"log",q:"Il faut 5 minutes pour scier une bûche en 2 morceaux. Combien de temps faut-il pour la scier en 5 morceaux ?",o:["25 min","15 min","20 min","30 min"],a:2,e:"5 morceaux exigent 4 coupes : 4 × 5 = 20 minutes.",s:"Banque logique"},
// --- Intrus ---
{id:"lo2-175",t:"log",q:"Trouvez l'intrus : 2 – 4 – 8 – 14 – 16 – 32",o:["14","8","16","32"],a:0,e:"Tous sont des puissances de 2, sauf 14.",s:"Banque logique"},
{id:"lo2-176",t:"log",q:"Trouvez l'intrus : 8 – 27 – 64 – 100 – 125",o:["27","100","64","125"],a:1,e:"Tous sont des cubes (2³, 3³, 4³, 5³), sauf 100.",s:"Banque logique"},
{id:"lo2-177",t:"log",q:"Trouvez l'intrus : 24 – 36 – 48 – 54 – 60 – 72",o:["36","48","54","60"],a:2,e:"Tous sont des multiples de 12, sauf 54.",s:"Banque logique"},
{id:"lo2-178",t:"log",q:"Trouvez l'intrus : 3 – 7 – 15 – 31 – 62 – 127",o:["7","31","127","62"],a:3,e:"Chaque terme devrait valoir le double du précédent plus 1 (puissances de 2 moins 1) : on attend 63, pas 62.",s:"Banque logique"},
{id:"lo2-179",t:"log",q:"Trouvez l'intrus : Tribunal administratif – Cour administrative d'appel – Conseil d'État – Sénat",o:["Sénat","Tribunal administratif","Cour administrative d'appel","Conseil d'État"],a:0,e:"Les trois autres sont des juridictions : elles forment l'ordre administratif (tribunaux administratifs, cours administratives d'appel et, au sommet, Conseil d'État). Le Sénat est une assemblée parlementaire.",s:"Banque logique"},
{id:"lo2-180",t:"log",q:"Trouvez l'intrus : TVA – Accises – Droits de douane – Impôt sur les sociétés",o:["TVA","Impôt sur les sociétés","Accises","Droits de douane"],a:1,e:"L'impôt sur les sociétés est un impôt direct ; la TVA, les accises et les droits de douane sont des impôts indirects.",s:"Banque logique"},
{id:"lo2-181",t:"log",q:"Trouvez l'intrus : Mercure – Vénus – Lune – Mars",o:["Mercure","Vénus","Lune","Mars"],a:2,e:"La Lune est un satellite naturel ; les trois autres sont des planètes.",s:"Banque logique"},
{id:"lo2-182",t:"log",q:"Trouvez l'intrus : Commune – Département – Canton – Région",o:["Commune","Département","Région","Canton"],a:3,e:"Commune, département et région sont des collectivités territoriales ; le canton n'est qu'une circonscription électorale.",s:"Banque logique"},
{id:"lo2-183",t:"log",q:"Trouvez l'intrus : Octet – Kilooctet – Mégahertz – Gigaoctet",o:["Mégahertz","Octet","Kilooctet","Gigaoctet"],a:0,e:"Le mégahertz mesure une fréquence ; les autres mesurent une quantité d'information.",s:"Banque logique"},
{id:"lo2-184",t:"log",q:"Trouvez l'intrus : AIMER – MARIE – MAIRE – MAIRIE – RAMIE",o:["AIMER","MAIRIE","MAIRE","RAMIE"],a:1,e:"AIMER, MARIE, MAIRE et RAMIE sont des anagrammes (A, E, I, M, R) ; MAIRIE a une lettre de plus.",s:"Banque logique"},
// --- Analogies ---
{id:"lo2-185",t:"log",q:"Pied est à chaussure ce que main est à :",o:["Bague","Bras","Gant","Doigt"],a:2,e:"La chaussure habille le pied comme le gant habille la main.",s:"Banque logique"},
{id:"lo2-186",t:"log",q:"2 est à 8 ce que 3 est à 27. De même, 4 est à :",o:["16","48","81","64"],a:3,e:"On élève au cube : 2³ = 8, 3³ = 27, 4³ = 64.",s:"Banque logique"},
{id:"lo2-187",t:"log",q:"Livre est à bibliothèque ce que tableau est à :",o:["Musée","Peintre","Cadre","Toile"],a:0,e:"C'est le lieu où l'on conserve et présente l'objet.",s:"Banque logique"},
{id:"lo2-188",t:"log",q:"ABC est à DEF ce que MNO est à :",o:["NOP","PQR","OPQ","QRS"],a:1,e:"On avance de trois lettres : M → P, N → Q, O → R.",s:"Banque logique"},
{id:"lo2-189",t:"log",q:"BD est à FH ce que JL est à :",o:["MO","NO","NP","OQ"],a:2,e:"On avance de quatre lettres : J → N, L → P.",s:"Banque logique"},
{id:"lo2-190",t:"log",q:"En tant que collectivités territoriales, commune est à maire ce que département est à :",o:["Préfet","Sous-préfet","Conseiller régional","Président du conseil départemental"],a:3,e:"L'exécutif élu de la commune est le maire ; celui du département est le président du conseil départemental (le préfet représente l'État).",s:"Banque logique"},
{id:"lo2-191",t:"log",q:"Lundi est à mercredi ce que jeudi est à :",o:["Samedi","Vendredi","Dimanche","Mardi"],a:0,e:"On avance de deux jours.",s:"Banque logique"},
{id:"lo2-192",t:"log",q:"Décret est à pouvoir exécutif ce que loi est à :",o:["Pouvoir judiciaire","Pouvoir législatif","Conseil constitutionnel","Conseil d'État"],a:1,e:"Le décret est un acte du pouvoir exécutif ; la loi est votée par le Parlement, qui exerce le pouvoir législatif.",s:"Banque logique"},
{id:"lo2-193",t:"log",q:"Cause est à effet ce que prémisse est à :",o:["Hypothèse","Raisonnement","Conclusion","Preuve"],a:2,e:"La prémisse précède et fonde la conclusion, comme la cause produit l'effet.",s:"Banque logique"},
// --- Tableaux de nombres décrits en texte ---
{id:"lo2-194",t:"log",q:"Tableau de nombres. Ligne 1 : 2, 4, 6. Ligne 2 : 3, 6, 9. Ligne 3 : 4, 8, ?. Quel nombre manque ?",o:["10","14","16","12"],a:3,e:"Chaque ligne donne le premier nombre multiplié par 1, 2 puis 3 : 4 × 3 = 12.",s:"Banque logique"},
{id:"lo2-195",t:"log",q:"Tableau de nombres. Ligne 1 : 3, 5, 8. Ligne 2 : 4, 7, 11. Ligne 3 : 6, 9, ?. Quel nombre manque ?",o:["15","12","13","18"],a:0,e:"Le 3e nombre de chaque ligne est la somme des deux premiers : 6 + 9 = 15.",s:"Banque logique"},
{id:"lo2-196",t:"log",q:"Tableau de nombres. Ligne 1 : 2, 3, 6. Ligne 2 : 4, 5, 20. Ligne 3 : 7, 3, ?. Quel nombre manque ?",o:["10","21","14","24"],a:1,e:"Le 3e nombre de chaque ligne est le produit des deux premiers : 7 × 3 = 21.",s:"Banque logique"},
{id:"lo2-197",t:"log",q:"Tableau de nombres. Ligne 1 : 5, 3, 16. Ligne 2 : 6, 2, 16. Ligne 3 : 7, 4, ?. Quel nombre manque ?",o:["24","28","22","33"],a:2,e:"Le 3e nombre vaut le double de la somme des deux premiers : (7 + 4) × 2 = 22.",s:"Banque logique"},
{id:"lo2-198",t:"log",q:"Tableau de nombres. Ligne 1 : 8, 2, 4. Ligne 2 : 15, 3, 5. Ligne 3 : 24, 6, ?. Quel nombre manque ?",o:["3","8","18","4"],a:3,e:"Le 3e nombre est le quotient des deux premiers : 24 / 6 = 4.",s:"Banque logique"},
{id:"lo2-199",t:"log",q:"Tableau de nombres. Colonne 1 : 1, 2, 3. Colonne 2 : 1, 4, 9. Colonne 3 : 1, 8, ?. Quel nombre manque ?",o:["27","12","16","24"],a:0,e:"La colonne 2 contient les carrés de la colonne 1, la colonne 3 les cubes : 3³ = 27.",s:"Banque logique"},
{id:"lo2-200",t:"log",q:"Tableau de nombres. Ligne 1 : 3, 4, 25. Ligne 2 : 5, 12, 169. Ligne 3 : 6, 8, ?. Quel nombre manque ?",o:["48","100","64","196"],a:1,e:"Le 3e nombre est la somme des carrés des deux premiers : 36 + 64 = 100.",s:"Banque logique"},
{id:"lo2-201",t:"log",q:"Tableau de nombres. Ligne 1 : 2, 5, 12. Ligne 2 : 3, 4, 15. Ligne 3 : 6, 2, ?. Quel nombre manque ?",o:["12","14","18","20"],a:2,e:"Le 3e nombre vaut a × b + a : 2 × 5 + 2 = 12, 3 × 4 + 3 = 15, 6 × 2 + 6 = 18.",s:"Banque logique"},
{id:"lo2-202",t:"log",q:"Carré magique de 3 × 3 (même somme sur chaque ligne, colonne et diagonale). Ligne 1 : 2, 7, 6. Ligne 2 : 9, 5, 1. Ligne 3 : 4, ?, 8. Quel nombre manque ?",o:["5","10","13","3"],a:3,e:"La somme magique est 2 + 7 + 6 = 15 : 15 − 4 − 8 = 3 (et 7 + 5 + 3 = 15 dans la colonne).",s:"Banque logique"},
{id:"lo2-203",t:"log",q:"Pyramide de nombres : la base est 3, 5, 2, 6, et chaque case vaut la somme des deux cases sur lesquelles elle repose. Quel nombre figure au sommet ?",o:["30","26","28","32"],a:0,e:"Étage 2 : 8, 7, 8 ; étage 3 : 15, 15 ; sommet : 30.",s:"Banque logique"},
// --- Conversions et unités ---
{id:"lo2-204",t:"log",q:"Combien de secondes compte une journée ?",o:["3 600","86 400","36 000","864 000"],a:1,e:"24 × 60 × 60 = 86 400 secondes.",s:"Banque logique"},
{id:"lo2-205",t:"log",q:"À quelle durée correspondent 2,75 heures ?",o:["2 h 7 min","2 h 34 min","2 h 45 min","3 h 15 min"],a:2,e:"0,75 h × 60 = 45 min : 2 h 45 min.",s:"Banque logique"},
{id:"lo2-206",t:"log",q:"Une vitesse de 36 km/h correspond à combien de mètres par seconde ?",o:["3,6 m/s","36 m/s","100 m/s","10 m/s"],a:3,e:"36 000 m en 3 600 s : 10 m/s (on divise les km/h par 3,6).",s:"Banque logique"},
{id:"lo2-207",t:"log",q:"Un terrain rectangulaire mesure 250 m sur 80 m. Quelle est sa surface en hectares ?",o:["2 ha","0,2 ha","20 ha","200 ha"],a:0,e:"250 × 80 = 20 000 m² ; 1 ha = 10 000 m², soit 2 ha.",s:"Banque logique"},
{id:"lo2-208",t:"log",q:"Combien de minutes compte une semaine ?",o:["1 440","10 080","8 640","100 800"],a:1,e:"7 × 24 × 60 = 10 080 minutes.",s:"Banque logique"},
{id:"lo2-209",t:"log",q:"Un robinet débite 12 litres par minute. Combien de temps faut-il pour remplir une cuve de 1,5 m³ ?",o:["1 h 25","2 h 15","2 h 05","12 h 30"],a:2,e:"1,5 m³ = 1 500 L ; 1 500 / 12 = 125 minutes, soit 2 h 05.",s:"Banque logique"},
{id:"lo2-210",t:"log",q:"Sur une carte à l'échelle 1/50 000, quelle distance réelle représentent 6 cm ?",o:["300 m","30 km","300 km","3 km"],a:3,e:"6 cm × 50 000 = 300 000 cm = 3 km.",s:"Banque logique"},
{id:"lo2-211",t:"log",q:"Une connexion offre un débit de 100 Mbit/s. Combien de mégaoctets peut-elle transférer, au mieux, en une seconde ?",o:["12,5 Mo","8 Mo","100 Mo","800 Mo"],a:0,e:"1 octet = 8 bits : 100 / 8 = 12,5 Mo par seconde.",s:"Banque logique"},
{id:"lo2-158",t:"log",q:"Un trajet se fait à 60 km/h à l'aller et à 40 km/h au retour, sur la même distance. Quelle est la vitesse moyenne sur l'aller-retour ?",o:["45 km/h","50 km/h","52 km/h","48 km/h"],a:3,e:"Sur 120 km : 2 h à l'aller, 3 h au retour ; 240 km en 5 h = 48 km/h (et non 50).",s:"Banque logique"},
{id:"lo2-164",t:"log",q:"Un prix subit trois hausses successives de 10 %. Quelle est sa hausse totale ?",o:["30 %","33,1 %","31 %","33 %"],a:1,e:"1,1 × 1,1 × 1,1 = 1,331, soit + 33,1 %.",s:"Banque logique"},
{id:"lo2-174",t:"log",q:"La moyenne de 4 notes est 12. Quelle 5e note faut-il obtenir pour que la moyenne passe à 13 ?",o:["13","15","16","17"],a:3,e:"Total visé : 5 × 13 = 65 ; total acquis : 4 × 12 = 48 ; il faut 17.",s:"Banque logique"}
);
